						short: "\"It takes two\" is the expression, and the opposition is created by dividing the circle by 2. Therein lies the key to the meaning of this aspect: relationship. People with oppositions seek out others as if to mirror their own internal struggles. They learn about themselves through interactions with others. Very often, oppositions cause us to swing from one side to the other and we feel torn.",
						long: "Oppositions represent a state of divided loyalties. Inner discontent, uncertainty, and insecurity can be a result. While a square is urgent and courageous, an opposition is unsure and wavering. When we use our oppositions correctly, we are more willing to consider the other side and we can be adept negotiators. Unlike squares, which demand direct action, oppositions drive us to seek balance through relationships and external mirrors. People with strong oppositions tend to be insightful and seek meaning through their connections with others, sometimes projecting their own qualities onto partners. The key to working with oppositions is developing objectivity: learning to hold two seemingly contradictory truths at once and finding the creative synthesis between them.",
