				description: "The fifth house is a house of creativity and governs education, entertainment and artistic talent. Physically, the creative energy of this house can manifest as our children. Putra means son in Sanskrit, even though in this case it indicates children as a whole. The creative energy of the fifth house gives birth to new ideas, and the \"children\" revealed can also manifest as creative endeavors. The creative mind is intuitive and can sometimes perceive the future. The fifth house is a house of \"purva punya\", which translates as past good deeds. This is an auspicious house and can give good fortune and luck due to previous good karma. The fifth house is a house of dharma. This house governs spiritual tools and techniques for achieving greater awareness, including the use of mantra, meditation and the reading of spiritual texts.",
